import { createRoute, z } from '@hono/zod-openapi'

type EnclosedInStringPropertyType = string

const EnclosedInStringPropertySchema: z.ZodType<EnclosedInStringPropertyType> = z
  .string()
  .openapi({
    'x-pattern':
      '\\([\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF]\\|[^\\S\\r\\n"\']\\)*',
  })
  .openapi('EnclosedInStringProperty')

type EnclosedInStringPropertiesType = z.infer<typeof EnclosedInStringPropertySchema>[]

const MappingSchema: z.ZodType<MappingType> = z
  .lazy(() =>
    z
      .object({
        ToKey: EnclosedInStringPropertySchema.and(
          z
            .any()
            .openapi({
              description:
                'After the apply mapping, what the name of the column should be. Can be the same as <code>FromPath</code>.',
            }),
        ).exactOptional(),
        FromPath: EnclosedInStringPropertiesSchema.and(
          z.any().openapi({ description: 'The table or column to be modified.' }),
        ).exactOptional(),
        FromType: EnclosedInStringPropertySchema.and(
          z.any().openapi({ description: 'The type of the data to be modified.' }),
        ).exactOptional(),
        ToType: EnclosedInStringPropertySchema.and(
          z.any().openapi({ description: 'The data type that the data is to be modified to.' }),
        ).exactOptional(),
        Dropped: BoxedBooleanSchema.and(
          z.any().openapi({ description: 'If true, then the column is removed.' }),
        ).exactOptional(),
        Children: MappingsSchema.and(
          z
            .any()
            .openapi({
              description:
                '<p>Only applicable to nested data structures. If you want to change the parent structure, but also one of its children, you can fill out this data strucutre. It is also <code>Mapping</code>, but its <code>FromPath</code> will be the parent\'s <code>FromPath</code> plus the <code>FromPath</code> from this structure.</p> <p>For the children part, suppose you have the structure:</p> <p> <code>{ "FromPath": "OuterStructure", "ToKey": "OuterStructure", "ToType": "Struct", "Dropped": false, "Chidlren": [{ "FromPath": "inner", "ToKey": "inner", "ToType": "Double", "Dropped": false, }] }</code> </p> <p>You can specify a <code>Mapping</code> that looks like:</p> <p> <code>{ "FromPath": "OuterStructure", "ToKey": "OuterStructure", "ToType": "Struct", "Dropped": false, "Chidlren": [{ "FromPath": "inner", "ToKey": "inner", "ToType": "Double", "Dropped": false, }] }</code> </p>',
            }),
        ).exactOptional(),
      })
      .openapi({ description: 'Specifies the mapping of data property keys.', required: [] }),
  )
  .openapi('Mapping')

type MappingsType = z.infer<typeof MappingSchema>[]

type BoxedBooleanType = boolean

const NameStringSchema = z
  .string()
  .min(1)
  .max(255)
  .openapi({ 'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\t]*' })
  .openapi('NameString')

const ClassificationSchema = z.string().openapi('Classification')

const TimestampSchema = z.iso.datetime({ offset: true }).openapi('Timestamp')

const VersionIdSchema = z.int().openapi('VersionId')

const GrokPatternSchema = z
  .string()
  .min(1)
  .max(2048)
  .openapi({ 'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\t]*' })
  .openapi('GrokPattern')

const CustomPatternsSchema = z
  .string()
  .min(0)
  .max(16000)
  .openapi({
    'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
  })
  .openapi('CustomPatterns')

const GrokClassifierSchema = z
  .object({
    Name: NameStringSchema.and(z.any().openapi({ description: 'The name of the classifier.' })),
    Classification: ClassificationSchema.and(
      z
        .any()
        .openapi({
          description:
            'An identifier of the data format that the classifier matches, such as Twitter, JSON, Omniture logs, and so on.',
        }),
    ),
    CreationTime: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was registered.' }),
    ).exactOptional(),
    LastUpdated: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was last updated.' }),
    ).exactOptional(),
    Version: VersionIdSchema.and(
      z.any().openapi({ description: 'The version of this classifier.' }),
    ).exactOptional(),
    GrokPattern: GrokPatternSchema.and(
      z
        .any()
        .openapi({
          description:
            'The grok pattern applied to a data store by this classifier. For more information, see built-in patterns in <a href="https://docs.aws.amazon.com/glue/latest/dg/custom-classifier.html">Writing Custom Classifiers</a>.',
        }),
    ),
    CustomPatterns: CustomPatternsSchema.and(
      z
        .any()
        .openapi({
          description:
            'Optional custom grok patterns defined by this classifier. For more information, see custom patterns in <a href="https://docs.aws.amazon.com/glue/latest/dg/custom-classifier.html">Writing Custom Classifiers</a>.',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['Name', 'Classification', 'GrokPattern'],
    description: 'A classifier that uses <code>grok</code> patterns.',
  })
  .openapi('GrokClassifier')

const RowTagSchema = z.string().openapi('RowTag')

const XMLClassifierSchema = z
  .object({
    Name: NameStringSchema.and(z.any().openapi({ description: 'The name of the classifier.' })),
    Classification: ClassificationSchema.and(
      z
        .any()
        .openapi({ description: 'An identifier of the data format that the classifier matches.' }),
    ),
    CreationTime: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was registered.' }),
    ).exactOptional(),
    LastUpdated: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was last updated.' }),
    ).exactOptional(),
    Version: VersionIdSchema.and(
      z.any().openapi({ description: 'The version of this classifier.' }),
    ).exactOptional(),
    RowTag: RowTagSchema.and(
      z
        .any()
        .openapi({
          description:
            'The XML tag designating the element that contains each record in an XML document being parsed. This can\'t identify a self-closing element (closed by <code>/&gt;</code>). An empty row element that contains only attributes can be parsed as long as it ends with a closing tag (for example, <code>&lt;row item_a="A" item_b="B"&gt;&lt;/row&gt;</code> is okay, but <code>&lt;row item_a="A" item_b="B" /&gt;</code> is not).',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['Name', 'Classification'],
    description: 'A classifier for <code>XML</code> content.',
  })
  .openapi('XMLClassifier')

const JsonPathSchema = z.string().openapi('JsonPath')

const JsonClassifierSchema = z
  .object({
    Name: NameStringSchema.and(z.any().openapi({ description: 'The name of the classifier.' })),
    CreationTime: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was registered.' }),
    ).exactOptional(),
    LastUpdated: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was last updated.' }),
    ).exactOptional(),
    Version: VersionIdSchema.and(
      z.any().openapi({ description: 'The version of this classifier.' }),
    ).exactOptional(),
    JsonPath: JsonPathSchema.and(
      z
        .any()
        .openapi({
          description:
            'A <code>JsonPath</code> string defining the JSON data for the classifier to classify. Glue supports a subset of JsonPath, as described in <a href="https://docs.aws.amazon.com/glue/latest/dg/custom-classifier.html#custom-classifier-json">Writing JsonPath Custom Classifiers</a>.',
        }),
    ),
  })
  .openapi({
    required: ['Name', 'JsonPath'],
    description: 'A classifier for <code>JSON</code> content.',
  })
  .openapi('JsonClassifier')

const CsvColumnDelimiterSchema = z
  .string()
  .regex(/[^\r\n]/)
  .length(1)
  .openapi('CsvColumnDelimiter')

const CsvQuoteSymbolSchema = z
  .string()
  .regex(/[^\r\n]/)
  .length(1)
  .openapi('CsvQuoteSymbol')

const CsvHeaderOptionSchema = z.enum(['UNKNOWN', 'PRESENT', 'ABSENT']).openapi('CsvHeaderOption')

const CsvHeaderSchema = z.array(NameStringSchema).openapi('CsvHeader')

const NullableBooleanSchema = z.boolean().openapi('NullableBoolean')

const CustomDatatypesSchema = z.array(NameStringSchema).openapi('CustomDatatypes')

const CsvClassifierSchema = z
  .object({
    Name: NameStringSchema.and(z.any().openapi({ description: 'The name of the classifier.' })),
    CreationTime: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was registered.' }),
    ).exactOptional(),
    LastUpdated: TimestampSchema.and(
      z.any().openapi({ description: 'The time that this classifier was last updated.' }),
    ).exactOptional(),
    Version: VersionIdSchema.and(
      z.any().openapi({ description: 'The version of this classifier.' }),
    ).exactOptional(),
    Delimiter: CsvColumnDelimiterSchema.and(
      z
        .any()
        .openapi({
          description: 'A custom symbol to denote what separates each column entry in the row.',
        }),
    ).exactOptional(),
    QuoteSymbol: CsvQuoteSymbolSchema.and(
      z
        .any()
        .openapi({
          description:
            'A custom symbol to denote what combines content into a single column value. It must be different from the column delimiter.',
        }),
    ).exactOptional(),
    ContainsHeader: CsvHeaderOptionSchema.and(
      z.any().openapi({ description: 'Indicates whether the CSV file contains a header.' }),
    ).exactOptional(),
    Header: CsvHeaderSchema.and(
      z.any().openapi({ description: 'A list of strings representing column names.' }),
    ).exactOptional(),
    DisableValueTrimming: NullableBooleanSchema.and(
      z
        .any()
        .openapi({
          description:
            'Specifies not to trim values before identifying the type of column values. The default value is <code>true</code>.',
        }),
    ).exactOptional(),
    AllowSingleColumn: NullableBooleanSchema.and(
      z
        .any()
        .openapi({ description: 'Enables the processing of files that contain only one column.' }),
    ).exactOptional(),
    CustomDatatypeConfigured: NullableBooleanSchema.and(
      z.any().openapi({ description: 'Enables the custom datatype to be configured.' }),
    ).exactOptional(),
    CustomDatatypes: CustomDatatypesSchema.and(
      z
        .any()
        .openapi({
          description:
            'A list of custom datatypes including "BINARY", "BOOLEAN", "DATE", "DECIMAL", "DOUBLE", "FLOAT", "INT", "LONG", "SHORT", "STRING", "TIMESTAMP".',
        }),
    ).exactOptional(),
  })
  .openapi({ required: ['Name'], description: 'A classifier for custom <code>CSV</code> content.' })
  .openapi('CsvClassifier')

type ClassifierType = {
  GrokClassifier?: z.infer<typeof GrokClassifierSchema> & { [key: string]: unknown }
  XMLClassifier?: z.infer<typeof XMLClassifierSchema> & { [key: string]: unknown }
  JsonClassifier?: z.infer<typeof JsonClassifierSchema> & { [key: string]: unknown }
  CsvClassifier?: z.infer<typeof CsvClassifierSchema> & { [key: string]: unknown }
}

const ColumnStatisticsTypeSchema = z
  .enum(['BOOLEAN', 'DATE', 'DECIMAL', 'DOUBLE', 'LONG', 'STRING', 'BINARY'])
  .openapi('ColumnStatisticsType')

const NonNegativeLongSchema = z.int().min(0).openapi('NonNegativeLong')

const BooleanColumnStatisticsDataSchema = z
  .object({
    NumberOfTrues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of true values in the column.' }),
    ),
    NumberOfFalses: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of false values in the column.' }),
    ),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
  })
  .openapi({
    required: ['NumberOfTrues', 'NumberOfFalses', 'NumberOfNulls'],
    description: 'Defines column statistics supported for Boolean data columns.',
  })
  .openapi('BooleanColumnStatisticsData')

const DateColumnStatisticsDataSchema = z
  .object({
    MinimumValue: TimestampSchema.and(
      z.any().openapi({ description: 'The lowest value in the column.' }),
    ).exactOptional(),
    MaximumValue: TimestampSchema.and(
      z.any().openapi({ description: 'The highest value in the column.' }),
    ).exactOptional(),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
    NumberOfDistinctValues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of distinct values in a column.' }),
    ),
  })
  .openapi({
    required: ['NumberOfNulls', 'NumberOfDistinctValues'],
    description: 'Defines column statistics supported for timestamp data columns.',
  })
  .openapi('DateColumnStatisticsData')

const BlobSchema = z.string().openapi('Blob')

const IntegerSchema = z.int().openapi('Integer')

const DecimalNumberSchema = z
  .object({
    UnscaledValue: BlobSchema.and(z.any().openapi({ description: 'The unscaled numeric value.' })),
    Scale: IntegerSchema.and(
      z
        .any()
        .openapi({
          description:
            'The scale that determines where the decimal point falls in the unscaled value.',
        }),
    ),
  })
  .openapi({
    required: ['UnscaledValue', 'Scale'],
    description: 'Contains a numeric value in decimal format.',
  })
  .openapi('DecimalNumber')

const DecimalColumnStatisticsDataSchema = z
  .object({
    MinimumValue: DecimalNumberSchema.and(
      z.any().openapi({ description: 'The lowest value in the column.' }),
    ).exactOptional(),
    MaximumValue: DecimalNumberSchema.and(
      z.any().openapi({ description: 'The highest value in the column.' }),
    ).exactOptional(),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
    NumberOfDistinctValues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of distinct values in a column.' }),
    ),
  })
  .openapi({
    required: ['NumberOfNulls', 'NumberOfDistinctValues'],
    description: 'Defines column statistics supported for fixed-point number data columns.',
  })
  .openapi('DecimalColumnStatisticsData')

const DoubleSchema = z.float64().openapi('Double')

const DoubleColumnStatisticsDataSchema = z
  .object({
    MinimumValue: DoubleSchema.and(
      z.any().openapi({ description: 'The lowest value in the column.' }),
    ).exactOptional(),
    MaximumValue: DoubleSchema.and(
      z.any().openapi({ description: 'The highest value in the column.' }),
    ).exactOptional(),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
    NumberOfDistinctValues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of distinct values in a column.' }),
    ),
  })
  .openapi({
    required: ['NumberOfNulls', 'NumberOfDistinctValues'],
    description: 'Defines column statistics supported for floating-point number data columns.',
  })
  .openapi('DoubleColumnStatisticsData')

const LongSchema = z.int().openapi('Long')

const LongColumnStatisticsDataSchema = z
  .object({
    MinimumValue: LongSchema.and(
      z.any().openapi({ description: 'The lowest value in the column.' }),
    ).exactOptional(),
    MaximumValue: LongSchema.and(
      z.any().openapi({ description: 'The highest value in the column.' }),
    ).exactOptional(),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
    NumberOfDistinctValues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of distinct values in a column.' }),
    ),
  })
  .openapi({
    required: ['NumberOfNulls', 'NumberOfDistinctValues'],
    description: 'Defines column statistics supported for integer data columns.',
  })
  .openapi('LongColumnStatisticsData')

const NonNegativeDoubleSchema = z.float64().min(0).openapi('NonNegativeDouble')

const StringColumnStatisticsDataSchema = z
  .object({
    MaximumLength: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The size of the longest string in the column.' }),
    ),
    AverageLength: NonNegativeDoubleSchema.and(
      z.any().openapi({ description: 'The average string length in the column.' }),
    ),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
    NumberOfDistinctValues: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of distinct values in a column.' }),
    ),
  })
  .openapi({
    required: ['MaximumLength', 'AverageLength', 'NumberOfNulls', 'NumberOfDistinctValues'],
    description: 'Defines column statistics supported for character sequence data values.',
  })
  .openapi('StringColumnStatisticsData')

const BinaryColumnStatisticsDataSchema = z
  .object({
    MaximumLength: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The size of the longest bit sequence in the column.' }),
    ),
    AverageLength: NonNegativeDoubleSchema.and(
      z.any().openapi({ description: 'The average bit sequence length in the column.' }),
    ),
    NumberOfNulls: NonNegativeLongSchema.and(
      z.any().openapi({ description: 'The number of null values in the column.' }),
    ),
  })
  .openapi({
    required: ['MaximumLength', 'AverageLength', 'NumberOfNulls'],
    description: 'Defines column statistics supported for bit sequence data values.',
  })
  .openapi('BinaryColumnStatisticsData')

type ColumnStatisticsDataType = {
  Type: z.infer<typeof ColumnStatisticsTypeSchema> & { [key: string]: unknown }
  BooleanColumnStatisticsData?: z.infer<typeof BooleanColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  DateColumnStatisticsData?: z.infer<typeof DateColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  DecimalColumnStatisticsData?: z.infer<typeof DecimalColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  DoubleColumnStatisticsData?: z.infer<typeof DoubleColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  LongColumnStatisticsData?: z.infer<typeof LongColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  StringColumnStatisticsData?: z.infer<typeof StringColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
  BinaryColumnStatisticsData?: z.infer<typeof BinaryColumnStatisticsDataSchema> & {
    [key: string]: unknown
  }
}

const DescriptionStringSchema = z
  .string()
  .min(0)
  .max(2048)
  .openapi({
    'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
  })
  .openapi('DescriptionString')

const URISchema = z
  .string()
  .min(1)
  .max(1024)
  .openapi({
    'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
  })
  .openapi('URI')

const ParametersMapValueSchema = z.string().max(512000).openapi('ParametersMapValue')

const ParametersMapSchema = z.record(z.string(), ParametersMapValueSchema).openapi('ParametersMap')

const DataLakePrincipalStringSchema = z.string().min(1).max(255).openapi('DataLakePrincipalString')

const DataLakePrincipalSchema = z
  .object({
    DataLakePrincipalIdentifier: DataLakePrincipalStringSchema.and(
      z.any().openapi({ description: 'An identifier for the Lake Formation principal.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'The Lake Formation principal.', required: [] })
  .openapi('DataLakePrincipal')

const PermissionSchema = z
  .enum([
    'ALL',
    'SELECT',
    'ALTER',
    'DROP',
    'DELETE',
    'INSERT',
    'CREATE_DATABASE',
    'CREATE_TABLE',
    'DATA_LOCATION_ACCESS',
  ])
  .openapi('Permission')

const PermissionListSchema = z.array(PermissionSchema).openapi('PermissionList')

const PrincipalPermissionsSchema = z
  .object({
    Principal: DataLakePrincipalSchema.and(
      z.any().openapi({ description: 'The principal who is granted permissions.' }),
    ).exactOptional(),
    Permissions: PermissionListSchema.and(
      z.any().openapi({ description: 'The permissions that are granted to the principal.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Permissions granted to a principal.', required: [] })
  .openapi('PrincipalPermissions')

const PrincipalPermissionsListSchema = z
  .array(PrincipalPermissionsSchema)
  .openapi('PrincipalPermissionsList')

const CatalogIdStringSchema = z
  .string()
  .min(1)
  .max(255)
  .openapi({ 'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\t]*' })
  .openapi('CatalogIdString')

const DatabaseIdentifierSchema = z
  .object({
    CatalogId: CatalogIdStringSchema.and(
      z.any().openapi({ description: 'The ID of the Data Catalog in which the database resides.' }),
    ).exactOptional(),
    DatabaseName: NameStringSchema.and(
      z.any().openapi({ description: 'The name of the catalog database.' }),
    ).exactOptional(),
    Region: NameStringSchema.and(
      z.any().openapi({ description: 'Region of the target database.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'A structure that describes a target database for resource linking.',
    required: [],
  })
  .openapi('DatabaseIdentifier')

const FederationIdentifierSchema = z
  .string()
  .min(1)
  .max(512)
  .openapi({ 'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\t]*' })
  .openapi('FederationIdentifier')

const FederatedDatabaseSchema = z
  .object({
    Identifier: FederationIdentifierSchema.and(
      z.any().openapi({ description: 'A unique identifier for the federated database.' }),
    ).exactOptional(),
    ConnectionName: NameStringSchema.and(
      z.any().openapi({ description: 'The name of the connection to the external metastore.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'A database that points to an entity outside the Glue Data Catalog.',
    required: [],
  })
  .openapi('FederatedDatabase')

type DatabaseType = {
  Name: z.infer<typeof NameStringSchema> & { [key: string]: unknown }
  Description?: z.infer<typeof DescriptionStringSchema> & { [key: string]: unknown }
  LocationUri?: z.infer<typeof URISchema> & { [key: string]: unknown }
  Parameters?: z.infer<typeof ParametersMapSchema> & { [key: string]: unknown }
  CreateTime?: z.infer<typeof TimestampSchema> & { [key: string]: unknown }
  CreateTableDefaultPermissions?: z.infer<typeof PrincipalPermissionsListSchema> & {
    [key: string]: unknown
  }
  TargetDatabase?: z.infer<typeof DatabaseIdentifierSchema> & { [key: string]: unknown }
  CatalogId?: z.infer<typeof CatalogIdStringSchema> & { [key: string]: unknown }
  FederatedDatabase?: z.infer<typeof FederatedDatabaseSchema> & { [key: string]: unknown }
}

